import{_ as e,o as t,c as l,a6 as c}from"./chunks/framework.CGCCzANv.js";const i=JSON.parse('{"title":"现代小说佳作100部","description":"","frontmatter":{"layout":"doc","title":"现代小说佳作100部","readingTime":"18 min read"},"headers":[],"relativePath":"电影和阅读/微信读书/文学_文学鉴赏/现代小说佳作100部.md","filePath":"电影和阅读/微信读书/文学_文学鉴赏/现代小说佳作100部.md"}'),a={name:"电影和阅读/微信读书/文学_文学鉴赏/现代小说佳作100部.md"};function r(p,o,q,u,b,k){return t(),l("div",null,[...o[0]||(o[0]=[c('<h1 id="现代小说佳作100部" tabindex="-1">现代小说佳作100部 <a class="header-anchor" href="#现代小说佳作100部" aria-label="Permalink to &quot;现代小说佳作100部&quot;">​</a></h1><p><img src="https://cdn.weread.qq.com/weread/cover/76/cpplatform_et9z7gzql7m3tivznhxto9/t6_cpplatform_et9z7gzql7m3tivznhxto91717141396.jpg" alt=" 现代小说佳作100部"></p><ul><li><strong>书名</strong>： 现代小说佳作100部</li><li><strong>作者</strong>： 邱华栋</li><li><strong>简介</strong>： 本书是当代著名作家、批评家邱华栋先生，以睿智的观察、精密的思考、深切的体悟，对普鲁斯特、乔伊斯、福克纳、海明威等100位现代世界级文学大师进行了全面的评述，从作家的生命历程与社会发展的变迁，从文学自身的传统到时代思潮的相互激荡，整合了文本、生平、个性、国族、宗教、政治、经济、地理等一 切相关方面，凝铸成一部丰富、多元、深厚的现代世界文学精神史。进入21世纪之后，随着全球化时代的深刻变革，世界文学的面貌出现了纷繁复杂的变化。小说不仅没有死亡，而是借助新型传媒具有了撒播效应，世界文学呈现出现代性和在地性，大众关注和精英阅读并行不悖的景象，一些文学大奖的影响也呈现出跨越国界、语种和地理范畴的面貌。这本《现代小说佳作100种》也许存在着个人的趣味和取舍，但从广义上说来，它凝聚了一个持续阅读和写作的文学人的眼光和对定评作家作品的关注，所选的绝大部分都是经典之作。在这里，我们与那些伟大的灵魂再次精神相遇。</li><li><strong>出版时间</strong>： 2024-05-01 00:00:00</li><li><strong>ISBN</strong>： 9787575300681</li><li><strong>分类</strong>： 文学-文学鉴赏</li><li><strong>出版社</strong>： 译林出版社</li><li><strong>PC地址</strong>： <a href="https://weread.qq.com/web/reader/86932130813ab8e3eg013e77" target="_blank" rel="noreferrer">https://weread.qq.com/web/reader/86932130813ab8e3eg013e77</a></li></ul><h3 id="鲍里斯·列昂尼多维奇·帕斯捷尔纳克-《日瓦戈医生》" tabindex="-1">鲍里斯·列昂尼多维奇·帕斯捷尔纳克：《日瓦戈医生》 <a class="header-anchor" href="#鲍里斯·列昂尼多维奇·帕斯捷尔纳克-《日瓦戈医生》" aria-label="Permalink to &quot;鲍里斯·列昂尼多维奇·帕斯捷尔纳克：《日瓦戈医生》&quot;">​</a></h3><blockquote><p>📌 鲍里斯·列昂尼多维奇·帕斯捷尔纳克1890年1月生于莫斯科一个艺术世家，父亲是一位画家，担任莫斯科美术和建筑学院的教授，曾经为文学大师列夫·托尔斯泰的《复活》配过插图。母亲是钢琴家，他们经常举行家庭聚会，家里来的都是文学艺术界的精英，包括列夫·托尔斯泰，奥地利诗人里尔克等。在这样的家庭环境熏陶下，帕斯捷尔纳克对文学艺术产生了极大兴趣。 ⏱ 2026-02-21 12:35:28</p></blockquote><blockquote><p>📌 1957年11月，《日瓦戈医生》意大利文版首先面世，随后不到一年的时间里，英文、法文、德文、西班牙文和俄文等版本纷纷在欧洲出版。1958年10月23日，瑞典皇家学院宣布，本年度的诺贝尔文学奖授予帕斯捷尔纳克，他获奖的理由是“在现代抒情诗和伟大的俄国小说传统领域所取得的巨大成就”。 ⏱ 2026-02-21 12:37:06</p></blockquote><blockquote><p>📌 在各方面的压力下，帕斯捷尔纳克发表声明，表示拒绝接受诺贝尔文学奖，也没有去斯德哥尔摩领奖。这个事件引发的轩然大波使帕斯捷尔纳克心力交瘁，备受打击。 ⏱ 2026-02-21 12:45:02</p></blockquote><blockquote><p>📌 虽然诗歌创作贯穿了帕斯捷尔纳克的一生，但小说《日瓦戈医生》却是他的代表作。这部小说翻译成中文近50万字，小说的叙述时间跨度有40年，主人公是日瓦戈医生。他在1917年十月革命前后的遭遇是主要情节，展现了渺小个人和广阔时代的关系。 ⏱ 2026-02-21 12:37:42</p></blockquote><blockquote><p>📌 尽管日瓦戈爱上了拉腊，但他是一个有家室的人，他克制住自己的感情，回到了莫斯科。 ⏱ 2026-02-21 12:38:59</p></blockquote><blockquote><p>📌 小说分上、下部，一共17章，上部主要讲述了日瓦戈的童年、在莫斯科的求学和十月革命前后那段岁月，下部描绘了日瓦戈前往西伯利亚的情况，结尾是日瓦戈医生留下来的24首诗，作为全书的结束。小说中一共塑造了一百多个人物，他们都围绕在日瓦戈的周围，在他的经历中隐现。小说模糊地表达了对暴力革命的怀疑，对苏联采取的一些政策造成的后果的质询，对俄罗斯传统文化被毁坏的深切痛惜。 ⏱ 2026-02-21 12:41:14</p></blockquote><blockquote><p>📌 小说中弥漫着一种沉郁的语调，叙述的语调还带着抒情色彩，这和俄罗斯大地的广袤和忧郁气质有关，也和作者是一个杰出的抒情诗人有关。 ⏱ 2026-02-21 12:41:38</p></blockquote><blockquote><p>📌 也是他的心灵自传式形象的外化，尽管日瓦戈在职业上被塑造为医生，可他同时又是一个诗人，与作者是一致的。 ⏱ 2026-02-21 12:45:25</p></blockquote><blockquote><p>📌 关于这部小说，帕斯捷尔纳克说：“我想通过这部小说，描绘俄罗斯最近四五十年的历史面貌，同时通过沉重、悲伤的主题的方方面面，使我能够表达自己对艺术、对福音书、对人在历史中的生存和其他等等的看法。”因此，人与历史的关系是这部小说的主题，帕斯捷尔纳克通过这部小说，表达了他的历史哲学，俄罗斯的文化和宗教、伟大文学传统的方方面面，都以各种影响与回响出现在这部小说里。 ⏱ 2026-02-21 12:46:17</p></blockquote><blockquote><p>📌 《日瓦戈医生》就是20世纪苏俄特定历史时期的留影。 ⏱ 2026-02-21 12:46:47</p></blockquote><h3 id="纳吉布·马哈福兹-《开罗三部曲》" tabindex="-1">纳吉布·马哈福兹：《开罗三部曲》 <a class="header-anchor" href="#纳吉布·马哈福兹-《开罗三部曲》" aria-label="Permalink to &quot;纳吉布·马哈福兹：《开罗三部曲》&quot;">​</a></h3><blockquote><p>📌 由于父亲经商，他的家境宽裕。纳吉布·马哈福兹从小就喜好读书，对文学有着浓厚的兴趣。18岁时开始尝试写短篇小说。 ⏱ 2026-02-21 12:48:59</p></blockquote><blockquote><p>📌 1939年他出版了第一部小说，讲述了古代埃及法老时期的故事，以辉煌的古埃及历史体现民族文化自豪感。 ⏱ 2026-02-21 12:49:15</p></blockquote><blockquote><p>📌 1988年获得诺贝尔文学奖，获奖理由是：“他以大量刻画细致入微的作品，显示了洞察一切的现实主义，唤起人们树立对生活的信念——由此形成了为全世界赞赏的阿拉伯叙事语言艺术。” ⏱ 2026-02-21 12:58:58</p></blockquote><blockquote><p>📌 地理位置决定了埃及必然会受到来自地中海的希腊罗马文化的影响，还有来自两河流域的阿拉伯文明的影响，以及非洲大陆本土文明的滋润。在六千年的时间里，这几种文明形态在埃及交汇形成了独特的历史与文化。 ⏱ 2026-02-21 12:59:51</p></blockquote><blockquote><p>📌 给他的颁奖词中说：“马哈福兹最关注的问题之一是对时代本质的认识……在《开罗三部曲》中展现的现实生活宏伟画卷，为马哈福兹赢得了大量的读者，然而《我们街区的孩子》更令人产生惊讶的感觉。它多达114章，数字恰与《古兰经》相同，是一部真正意义上的人类精神史；它将呼之欲出的犹太教、基督教和伊斯兰教的先知们伪装成凡夫俗子，以对付现实社会的紧张局面。 ⏱ 2026-02-21 13:00:42</p></blockquote><h3 id="奥尔罕·帕慕克-《我的名字叫红》" tabindex="-1">奥尔罕·帕慕克：《我的名字叫红》 <a class="header-anchor" href="#奥尔罕·帕慕克-《我的名字叫红》" aria-label="Permalink to &quot;奥尔罕·帕慕克：《我的名字叫红》&quot;">​</a></h3><blockquote><p>📌 土耳其的首都安卡拉位于国家中部，其文化地位比不上伊斯坦布尔。伊斯坦布尔有着辉煌的历史，在15、16世纪是奥斯曼帝国的首都，当时还叫君士坦丁堡 ⏱ 2026-02-21 12:11:39</p></blockquote><blockquote><p>📌 40多年来，以10多部精彩的小说和非虚构作品，成为当代最杰出作家之一。 ⏱ 2026-02-21 12:12:03</p></blockquote><blockquote><p>📌 小说讲述了伊斯坦布尔一个上层人物塞夫德特州长和他的儿子、孙子孙女三代人的故事。小说精雕细刻，细致地描绘出伊斯坦布尔在一个特定年代的人群，带有浓郁的时代哀伤感。 ⏱ 2026-02-21 12:12:35</p></blockquote><blockquote><p>📌 通过《塞夫德特和他的儿子们》和《寂静的房子》的写作，奥尔罕·帕慕克完成了他的早期写作阶段，进入到第二个阶段。在这个阶段里，现代小说技巧在他手下运用娴熟，他所擅长的多角度、多视点来描绘事件、人物和时代的手法也运用得炉火纯青， ⏱ 2026-02-21 12:13:33</p></blockquote><blockquote><p>📌 随着时间的推移，我们看见两个迥然不同的‘呼愁’出现，各自唤起某种独特的哲学传统。根据第一个传统，当我们对世俗享乐和物质利益投注过多时，便体验到所谓的‘呼愁’：其含义是‘你若对这无常人世如此投入，你若是善良诚实的回教徒，便不会如此在意世间的失落’。第二个传统出自苏菲神秘主义思想，为‘呼愁’一词以及失落与悲伤的生命定位提供一种较积极、较悲悯的认识。对苏菲派来说，‘呼愁’是因为不够靠近真主安拉、因为在这个世上为安拉做的事不够而感受到的一种苦闷。”在奥尔罕·帕慕克的所有小说中，似乎都弥漫着“呼愁”的情绪， ⏱ 2026-02-21 12:15:27</p></blockquote><blockquote><p>📌 伊斯坦布尔的‘呼愁’不仅仅是由音乐和诗歌唤起的情绪，也是一种看待我们共同生命的方式，不仅仅是一种精神状态，也是一种思想状态，最后既肯定了人生，又否定了人生……现在我们逐渐明白，‘呼愁’不是某个孤独之人的忧伤，而是数百万人共有的阴暗情绪。我想说明的是伊斯坦布尔整座城市的‘呼愁’。”进入奥尔罕·帕慕克的小说世界，深刻理解这一段话，才可以把握他的小说神魂。 ⏱ 2026-02-21 12:15:50</p></blockquote><blockquote><p>📌 1998年，奥尔罕·帕慕克出版长篇小说《我的名字叫红》。这部小说是他的代表作，小说的背景设在16世纪末期奥斯曼土耳其帝国时代，统治帝国的苏丹请一批细密画家制作一本伟大的书，用来赞颂苏丹的丰功伟绩和帝国的荣耀。一群卓越的细密画画家们开始为苏丹工作，很快，其中一个细密画画家就被谋杀了。是谁干的？原来，一位画家想用文艺复兴带来的透视绘画技法绘制细密画，但帝国的原教旨思想不允许带有阴影和透视的绘画出现。小说主人公由此展开了调查。小说的故事情节紧紧围绕离开家庭12年之久的青年黑，他回到伊斯坦布尔之后，不仅迎来一场期待已久的爱情，还遭遇到一个谋杀案。苏丹要求三天查出谁是凶手，于是，在逐步推理中，在排除一个个怀疑对象的过程中，小说也将结局推向了高潮。 ⏱ 2026-02-21 12:20:46</p></blockquote><blockquote><p>📌 这部小说采取了多声部的叙述手法，全书59个章节，几乎每个章节的叙述人都在变化，30多个叙述者轮番上阵，甚至墙上画中的狗也能讲述。围绕被谋杀的细密画家，展开了多个声音的交织叙述，各个声音之间互相佐证，成为旁证，形成了补充和反差，有时候感觉距离揭开谜底越来越近，可又觉得距离事实真相越来越远。这种多个角度的叙述手法，在奥尔罕·帕慕克写《寂静的房子》时就开始运用了，不过那时他的技法还比较简单，在《黑书》中以穿插报刊专栏文章的引文手法也实现了某种多声部叙述。在《我的名字叫红》中，多声部是一种令人吃惊的众声喧哗。 ⏱ 2026-02-21 12:21:35</p></blockquote><blockquote><p>📌 从小说的外形上看，侦探小说的壳完美地罩在小说上面，这是因为人类天生就喜欢猜谜，喜欢刨根问底，喜欢谜底被揭开。但去掉侦探小说的外壳，你会发现，原来这是一部历史小说，还是一部文化小说。 ⏱ 2026-02-21 12:23:40</p></blockquote><blockquote><p>📌 在《我的名字叫红》中，大量奥斯曼土耳其帝国在那个时代和西方的地中海国家交往的细节出现了。其中，关于宫廷书籍的制作，特别是关于细密画和意大利文艺复兴时期之间的互动关系，是小说着墨最多的地方。 ⏱ 2026-02-21 12:24:01</p></blockquote><blockquote><p>📌 奥尔罕·帕慕克说：“伊斯坦布尔的命运就是我的命运：我依附于这个城市，只因她造就了今天的我。”2005年，奥尔罕·帕慕克出版长篇非虚构自传体小说《伊斯坦布尔：一座城市的记忆》，引起了轰动。奥尔罕·帕慕克说：“要想传达伊斯坦布尔让儿时的我感受到的强烈‘呼愁’感，则必须描述奥斯曼帝国毁灭之后的城市历史，以及此一历史如何反映在这城市的‘美丽’风光以及其人民身上。” ⏱ 2026-02-21 12:25:19</p></blockquote><blockquote><p>📌 2007年，他出版了随笔集《别样的色彩：关于生活、艺术、书籍与城市》，收录了他的随笔和评论，自传性和独特感受性是这本书的特点，可以看到一个在生活、美术、文学和建筑中间自由穿梭的人，他打通了时间，把阅读和思考、写作和漫游变成了一种人生的乐趣。 ⏱ 2026-02-21 12:25:52</p></blockquote>',33)])])}const s=e(a,[["render",r]]);export{i as __pageData,s as default};
